// NEGOTIATION PREP — the case for the phone call, assembled from your own data.
//
// Issuers reduce rates, waive fees and open hardship plans routinely, and almost nobody asks. The
// call costs nothing: a retention conversation is not a credit application, so there is no hard pull
// and no score consequence to trying. What there IS, is a right ask and a wrong one — and getting
// that wrong is how a call that could have helped ends with a "no" on the record.
//
// THE ASK DEPENDS ON WHETHER YOU CAN PAY, and this is the judgement the module exists to make:
//
//   YOU CAN PAY      → a RATE REDUCTION, on the strength of tenure, a clean payment history, and a
//                      competing offer you can actually name. This is a customer worth keeping
//                      asking to be treated like one.
//   YOU CANNOT PAY   → a HARDSHIP PLAN, and the timing is the whole thing: entered BEFORE a missed
//                      payment it is an arrangement, and the account stays current on the report.
//                      Entered after, the delinquency is already reported and cannot be taken back.
//                      Asking for a rate cut in this situation wastes the one call you get.
//
// A FEE THAT HAS ALREADY LANDED IS A SEPARATE, EASIER CALL. First-offence waivers are close to
// routine and are granted to people who ask, so a recent late fee is its own ask and goes first —
// it is the cheapest win available and it does not spend any of the goodwill the rate call needs.
//
// The evidence here is only ever what the data actually supports. Absent evidence is ABSENT: a case
// that invents leverage produces a person confidently saying something an issuer can disprove from
// their own screen, which is worse than saying nothing.
import { type Money, money, scale } from "@/features/finance/lib/money";
import type { FeeAudit } from "@/features/finance/lib/fees";
import type { AccountPosition, Position } from "@/features/finance/lib/position";
import type { TransferOffer } from "@/features/finance/lib/transfer";
import { daysBetween } from "@/features/finance/lib/txn";

export type Ask = "fee-waiver" | "rate-reduction" | "hardship-plan";

export type Strength = "strong" | "moderate" | "weak";

export interface Evidence {
  /** What can actually be said on the call. */
  readonly claim: string;
  readonly strength: Strength;
  /** Where it came from, so it can be checked before it is repeated to a stranger. */
  readonly source: string;
}

export interface NegotiationCase {
  readonly account: string;
  readonly institution: string;
  readonly ask: Ask;
  /** Why THIS ask and not another. */
  readonly why: string;
  readonly evidence: readonly Evidence[];
  /** Things not to say, each with the reason it costs you. */
  readonly doNotSay: readonly string[];
  /** What a reasonable outcome looks like, so a partial win is not read as a failure. */
  readonly realistic: string;
  /** A year of the ask, if it is granted. Contingent, and labelled as such. */
  readonly annualValueIfWon: Money;
  readonly urgency?: string;
}

export interface NegotiationInput {
  readonly position: Position;
  /** `YYYY-MM-DD`. Passed in, never read from a clock. */
  readonly asOf: string;
  /** Whether the runway holds — the single fact that decides the ask. */
  readonly canPay: boolean;
  readonly fees?: FeeAudit;
  /** Real offers you could name on the call. The strongest lever there is. */
  readonly offers?: readonly TransferOffer[];
  /** Months the account has been open, where it is known. */
  readonly tenureMonths?: Readonly<Record<string, number>>;
  /** How much of a rate cut to model. Not a promise, a unit for the arithmetic. */
  readonly targetReduction?: number;
  /** A fee this recent is a live waiver candidate. */
  readonly feeWindowDays?: number;
  /** Utilisation above which closing this line would hurt the rest. */
  readonly utilisationConcern?: number;
}

const pct = (n: number): string => `${Math.round(n * 10000) / 100}%`;

/**
 * What overall utilisation would become if this line were CLOSED.
 *
 * The reason it matters is the reason "I'll close it" is dangerous advice: they might say yes. The
 * balance moves nowhere and the limit disappears, so utilisation across everything left jumps.
 */
export function utilisationIfClosed(position: Position, account: string): number | undefined {
  const lines = position.accounts.filter((a) => a.kind === "credit" && a.creditLimit);
  const remaining = lines.filter((a) => a.account !== account);
  const limit = remaining.reduce((n, a) => n + a.creditLimit!.minor, 0);
  if (limit <= 0) return undefined;
  const owed = lines.reduce((n, a) => n + (a.owed?.minor ?? 0), 0);
  return Math.round((owed / limit) * 1000) / 1000;
}

function gatherEvidence(a: AccountPosition, input: NegotiationInput): Evidence[] {
  const { fees, offers = [], tenureMonths = {} } = input;
  const out: Evidence[] = [];

  const tenure = tenureMonths[a.account];
  if (tenure !== undefined) {
    out.push({
      claim: `the account has been open ${tenure} month(s)`,
      // Under a year is not tenure, it is a trial period, and saying it out loud helps nobody.
      strength: tenure >= 36 ? "strong" : tenure >= 12 ? "moderate" : "weak",
      source: "months between the first and last transaction observed on this account",
    });
  }

  if (fees) {
    const mine = fees.fees.filter((f) => f.account === a.account);
    const late = mine.filter((f) => f.kind === "late" || f.kind === "nsf");
    if (late.length === 0) {
      // THE STRONGEST SINGLE CARD, and it is the one people forget they hold.
      out.push({
        claim: "no late or returned-payment fee appears anywhere in the statements held",
        strength: "strong",
        source: "the fee audit over every ingested statement",
      });
    } else {
      out.push({
        claim: `${late.length} late or returned-payment fee(s) appear, the most recent on ${late.map((f) => f.date).sort().pop()}`,
        strength: "weak",
        source: "the fee audit",
      });
    }
    const interest = mine.filter((f) => f.kind === "interest").reduce((n, f) => n + Math.abs(f.amount.minor), 0);
    if (interest > 0) {
      // Concrete, and their own number. "I have paid you X" is a harder sentence to wave away than
      // "your rate is high".
      out.push({
        claim: `${interest} minor units of interest have been paid to this account in the statements held`,
        strength: "strong",
        source: "the fee audit, interest rows only",
      });
    }
  }

  const better = offers
    .filter((o) => o.institution !== a.institution && o.promoApr < (a.apr ?? Infinity))
    .sort((x, y) => x.promoApr - y.promoApr)[0];
  if (better) {
    out.push({
      claim: `${better.institution} is offering ${pct(better.promoApr)} for ${better.promoMonths} months${better.offerExpires ? `, expiring ${better.offerExpires}` : ""}`,
      strength: "strong",
      source: "an offer supplied to this analysis — name it only if it is real and you would take it",
    });
  }

  if (a.utilisation !== undefined) {
    out.push({
      claim:
        a.utilisation <= 0.3
          ? `this line is only ${Math.round(a.utilisation * 100)}% used, which is what a low-risk customer looks like`
          : `this line is ${Math.round(a.utilisation * 100)}% used, which is what a customer worth retaining looks like`,
      strength: a.utilisation <= 0.3 ? "moderate" : "weak",
      source: "the position's utilisation for this account",
    });
  }

  return out;
}

export function prepareNegotiation(input: NegotiationInput): NegotiationCase[] {
  const {
    position,
    asOf,
    canPay,
    fees,
    targetReduction = 0.05,
    feeWindowDays = 120,
    utilisationConcern = 0.3,
  } = input;
  const currency = position.currency;
  const cases: NegotiationCase[] = [];

  for (const a of position.accounts) {
    if (!a.isDebt || !a.owed) continue;

    const evidence = gatherEvidence(a, input);
    const recentFees = (fees?.fees ?? []).filter(
      (f) =>
        f.account === a.account &&
        f.kind !== "interest" &&
        daysBetween(f.date, asOf) <= feeWindowDays &&
        daysBetween(f.date, asOf) >= 0,
    );

    const doNotSay: string[] = [];
    const closed = utilisationIfClosed(position, a.account);
    if (closed !== undefined && closed > utilisationConcern) {
      // THEY MIGHT SAY YES. The balance moves nowhere and the limit disappears.
      doNotSay.push(
        `do not threaten to close this account — if they accept, utilisation across everything left goes to ${Math.round(closed * 100)}%, and the balance has not moved an inch`,
      );
    }
    doNotSay.push("do not say you are considering bankruptcy unless you are — it can freeze the account and end the conversation you wanted");
    doNotSay.push("do not accept a deferral that CAPITALISES the interest without asking what it does to the balance");

    // THE CHEAPEST WIN FIRST. A waiver call does not spend the goodwill the rate call needs.
    if (recentFees.length) {
      const total = recentFees.reduce((n, f) => n + Math.abs(f.amount.minor), 0);
      cases.push({
        account: a.account,
        institution: a.institution,
        ask: "fee-waiver",
        why: `${recentFees.length} fee(s) totalling ${total} minor units landed in the last ${feeWindowDays} days, and a first-offence waiver is close to routine for anyone who asks`,
        evidence,
        doNotSay,
        realistic: "one fee waived is the usual outcome; several at once is not. Ask for the most recent one by name and date.",
        annualValueIfWon: money(total, currency),
        urgency: "fees are easiest to reverse in the cycle they appear — this gets harder every statement that passes",
      });
    }

    if (!canPay) {
      // THE TIMING IS THE WHOLE THING.
      cases.push({
        account: a.account,
        institution: a.institution,
        ask: "hardship-plan",
        why: "the runway does not hold, so a rate cut is not the ask — a hardship or forbearance arrangement is, and it is a different department and a different conversation",
        evidence,
        doNotSay: [
          ...doNotSay,
          "do not ask for a rate reduction in the same call — it signals you expect to keep revolving, and it is answered by a different team",
        ],
        realistic:
          "a fixed reduced rate for 6-12 months with the account reported CURRENT is a normal outcome; a written-off balance is not",
        annualValueIfWon: scale(a.owed, Math.min(a.apr ?? 0, 0.15)),
        urgency:
          "CALL BEFORE A PAYMENT IS MISSED. Entered before a delinquency this is an arrangement and the account stays current on the report; entered after, the delinquency is already reported and no arrangement takes it back.",
      });
      continue;
    }

    const strong = evidence.filter((e) => e.strength === "strong").length;
    cases.push({
      account: a.account,
      institution: a.institution,
      ask: "rate-reduction",
      // The call costing nothing is true either way, so it is said either way. It is the reason to
      // make the weak call as well as the strong one, and burying it in the strong branch would
      // leave the case with no evidence reading as a case not worth making.
      why:
        strong > 0
          ? `${strong} piece(s) of strong evidence support it. The call costs nothing — a retention conversation is not a credit application, so there is no hard pull.`
          : "there is little here to argue from, so this is a plain ask rather than a case. The call still costs nothing — a retention conversation is not a credit application, so there is no hard pull — and the answer is sometimes yes anyway.",
      evidence,
      doNotSay,
      realistic: `a reduction of 3-7 points is a normal outcome; ${pct(a.apr ?? 0)} going to zero is not. A "no" today does not stop you asking again in six months.`,
      annualValueIfWon: scale(a.owed, Math.min(targetReduction, a.apr ?? 0)),
    });
  }

  // Cheapest win first, then by what the ask is worth.
  const rank: Record<Ask, number> = { "fee-waiver": 0, "hardship-plan": 1, "rate-reduction": 2 };
  return cases.sort(
    (x, y) => rank[x.ask] - rank[y.ask] || y.annualValueIfWon.minor - x.annualValueIfWon.minor,
  );
}

/** Everything the calls are worth together, if every one lands. Contingent, and it says so. */
export const totalIfEveryAskLands = (cases: readonly NegotiationCase[], currency: string): Money =>
  money(cases.reduce((n, c) => n + c.annualValueIfWon.minor, 0), currency);

/** The order to make the calls in, with the one sentence that opens each. */
export const callOrder = (cases: readonly NegotiationCase[]): readonly string[] =>
  cases.map((c) => {
    if (c.ask === "fee-waiver") return `${c.institution}: "I saw a fee on my last statement and I'd like to ask for it to be waived."`;
    if (c.ask === "hardship-plan") return `${c.institution}: "I want to stay current and I'm not going to be able to at this rate. What hardship options do you have?"`;
    return `${c.institution}: "I've been a customer a while and I'm looking at my rate. What can you do?"`;
  });

