import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { Txn } from "@/features/finance/lib/txn";
import { auditFees } from "@/features/finance/lib/fees";
import type { AccountPosition, Position } from "@/features/finance/lib/position";
import type { TransferOffer } from "@/features/finance/lib/transfer";
import {
  type NegotiationInput,
  callOrder,
  prepareNegotiation,
  totalIfEveryAskLands,
  utilisationIfClosed,
} from "@/features/finance/lib/negotiate";

// SYNTHETIC FIXTURES ONLY. No real statement, balance, fee or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");
const tx = (date: string, description: string, major: number, account: string): Txn => ({
  date,
  description,
  amount: usd(major),
  account,
});

const CARD: AccountPosition = {
  account: "a",
  institution: "Alpha Card",
  kind: "credit",
  balance: usd(-4000),
  asOf: "2026-06-30",
  rolledForward: 0,
  isDebt: true,
  owed: usd(4000),
  apr: 0.2499,
  creditLimit: usd(6000),
  available: usd(2000),
  utilisation: 0.667,
  minimumPayment: usd(90),
};

const SECOND: AccountPosition = {
  ...CARD,
  account: "b",
  institution: "Beta Card",
  balance: usd(-500),
  owed: usd(500),
  apr: 0.1499,
  creditLimit: usd(9000),
  utilisation: 0.056,
};

const position = (accounts: AccountPosition[] = [CARD]): Position => ({
  asOf: "2026-06-30",
  currency: "USD",
  accounts,
  netWorth: usd(-4000),
  liquid: usd(500),
  totalDebt: usd(4000),
  dailyInterest: usd(3),
  minimumsDue: usd(90),
  complete: true,
  problems: [],
  provenance: "reconciled · synthetic",
});

const input = (over: Partial<NegotiationInput> = {}): NegotiationInput => ({
  position: position(),
  asOf: "2026-06-30",
  canPay: true,
  ...over,
});

const OFFER: TransferOffer = {
  id: "omega",
  institution: "Omega Bank",
  promoApr: 0,
  promoMonths: 18,
  transferFeeRate: 0.03,
  goToApr: 0.2299,
  offerExpires: "2026-08-31",
};

describe("THE ASK DEPENDS ON WHETHER YOU CAN PAY", () => {
  it("asks for a RATE REDUCTION when the runway holds", () => {
    const cases = prepareNegotiation(input({ canPay: true }));
    expect(cases.map((c) => c.ask)).toEqual(["rate-reduction"]);
    expect(cases[0].why).toContain("no hard pull");
  });

  it("asks for a HARDSHIP PLAN when it does not, and says a rate cut is the wrong ask", () => {
    const cases = prepareNegotiation(input({ canPay: false }));
    expect(cases.map((c) => c.ask)).toEqual(["hardship-plan"]);
    expect(cases[0].why).toContain("different department");
    // The rate call is not merely lower priority here — it is actively counterproductive.
    expect(cases[0].doNotSay.join(" ")).toContain("expect to keep revolving");
  });

  it("says CALL BEFORE A PAYMENT IS MISSED, because after it cannot be taken back", () => {
    // Entered before a delinquency it is an arrangement and the account stays current on the
    // report. Entered after, the delinquency is already reported. That is the whole timing.
    const cases = prepareNegotiation(input({ canPay: false }));
    expect(cases[0].urgency).toContain("BEFORE A PAYMENT IS MISSED");
    expect(cases[0].urgency).toContain("no arrangement takes it back");
  });

  it("gives one case per debt and none for an account that owes nothing", () => {
    const clear: AccountPosition = { ...SECOND, account: "c", owed: undefined, balance: usd(0) };
    const cases = prepareNegotiation(input({ position: position([CARD, SECOND, clear]) }));
    expect(cases.map((c) => c.account).sort()).toEqual(["a", "b"]);
  });
});

describe("the cheapest win goes first", () => {
  const fees = () =>
    auditFees(
      [
        tx("2026-06-05", "LATE FEE", -39, "a"),
        tx("2026-06-20", "INTEREST CHARGE", -82, "a"),
      ],
      "USD",
    );

  it("puts a recent fee waiver ahead of the rate call", () => {
    // A waiver call does not spend the goodwill the rate call needs, and it is the likelier yes.
    const cases = prepareNegotiation(input({ fees: fees() }));
    expect(cases.map((c) => c.ask)).toEqual(["fee-waiver", "rate-reduction"]);
    expect(cases[0].annualValueIfWon.minor).toBe(usd(39).minor);
    expect(cases[0].urgency).toContain("harder every statement that passes");
  });

  it("does NOT treat interest as a waivable fee", () => {
    const interestOnly = auditFees([tx("2026-06-20", "INTEREST CHARGE", -82, "a")], "USD");
    const cases = prepareNegotiation(input({ fees: interestOnly }));
    expect(cases.map((c) => c.ask)).toEqual(["rate-reduction"]);
  });

  it("lets a stale fee go — it is not a live waiver candidate", () => {
    const old = auditFees([tx("2025-06-05", "LATE FEE", -39, "a")], "USD");
    expect(prepareNegotiation(input({ fees: old })).map((c) => c.ask)).toEqual(["rate-reduction"]);
    expect(
      prepareNegotiation(input({ fees: old, feeWindowDays: 400 })).map((c) => c.ask),
    ).toEqual(["fee-waiver", "rate-reduction"]);
  });

  it("orders the calls, with the sentence that opens each", () => {
    const order = callOrder(prepareNegotiation(input({ fees: fees() })));
    expect(order[0]).toContain("waived");
    expect(order[1]).toContain("What can you do?");
  });
});

describe("evidence is only ever what the data supports", () => {
  it("calls a clean payment history STRONG, and it comes from the fee audit", () => {
    const clean = auditFees([tx("2026-06-20", "INTEREST CHARGE", -82, "a")], "USD");
    const e = prepareNegotiation(input({ fees: clean }))[0].evidence;
    const history = e.find((x) => x.claim.includes("no late"))!;
    expect(history.strength).toBe("strong");
    expect(history.source).toContain("fee audit");
  });

  it("does not claim a clean history when there is a late fee", () => {
    const late = auditFees([tx("2026-06-05", "LATE FEE", -39, "a")], "USD");
    const e = prepareNegotiation(input({ fees: late })).find((c) => c.ask === "rate-reduction")!.evidence;
    expect(e.some((x) => x.claim.includes("no late"))).toBe(false);
    expect(e.find((x) => x.claim.includes("late"))!.strength).toBe("weak");
  });

  it("quotes a real competing offer with its actual rate, and says to name it only if real", () => {
    const e = prepareNegotiation(input({ offers: [OFFER] }))[0].evidence;
    const lever = e.find((x) => x.claim.includes("Omega Bank"))!;
    expect(lever.claim).toContain("0% for 18 months");
    expect(lever.claim).toContain("2026-08-31");
    expect(lever.strength).toBe("strong");
    expect(lever.source).toContain("only if it is real");
  });

  it("ignores an offer that is not actually better, and the issuer's own offer", () => {
    const worse: TransferOffer = { ...OFFER, id: "w", institution: "Zed", promoApr: 0.2999 };
    const own: TransferOffer = { ...OFFER, id: "o", institution: "Alpha Card" };
    const e = prepareNegotiation(input({ offers: [worse, own] }))[0].evidence;
    expect(e.some((x) => x.claim.includes("Zed"))).toBe(false);
    expect(e.some((x) => x.claim.includes("Alpha Card is offering"))).toBe(false);
  });

  it("does not call under a year of tenure strong — that is a trial period, not tenure", () => {
    const short = prepareNegotiation(input({ tenureMonths: { a: 7 } }))[0].evidence;
    expect(short.find((x) => x.claim.includes("open 7"))!.strength).toBe("weak");
    const long = prepareNegotiation(input({ tenureMonths: { a: 48 } }))[0].evidence;
    expect(long.find((x) => x.claim.includes("open 48"))!.strength).toBe("strong");
  });

  it("says plainly when there is little to argue from, rather than inventing leverage", () => {
    // A case that invents leverage produces somebody confidently saying something the issuer can
    // disprove from their own screen, which is worse than saying nothing.
    const bare: AccountPosition = { ...CARD, utilisation: undefined, creditLimit: undefined, available: undefined };
    const c = prepareNegotiation(input({ position: position([bare]) }))[0];
    expect(c.evidence).toEqual([]);
    expect(c.why).toContain("a plain ask rather than a case");
    expect(c.why).toContain("sometimes yes anyway");
  });
});

describe("do not threaten to close — they might say yes", () => {
  it("warns when closing this line would push the rest above the concern line", () => {
    // The balance moves nowhere and the limit disappears, so utilisation across everything left
    // jumps. It is the advice most often given and most often wrong.
    const c = prepareNegotiation(input({ position: position([CARD, SECOND]) })).find((x) => x.account === "a")!;
    expect(c.doNotSay.join(" ")).toContain("do not threaten to close");
    expect(c.doNotSay.join(" ")).toContain("has not moved an inch");
  });

  it("computes what utilisation would BECOME, not what it is", () => {
    // $4,500 owed across both; closing Alpha leaves only Beta's $9,000 limit.
    expect(utilisationIfClosed(position([CARD, SECOND]), "a")).toBe(0.5);
    expect(utilisationIfClosed(position([CARD, SECOND]), "b")).toBe(0.75);
    expect(utilisationIfClosed(position([CARD]), "a")).toBeUndefined();
  });

  it("stays quiet about closing when it genuinely would not hurt", () => {
    const tiny: AccountPosition = { ...CARD, owed: usd(100), balance: usd(-100), utilisation: 0.017 };
    const roomy: AccountPosition = { ...SECOND, owed: undefined, balance: usd(0), creditLimit: usd(40_000) };
    const c = prepareNegotiation(input({ position: position([tiny, roomy]) })).find((x) => x.account === "a")!;
    expect(c.doNotSay.join(" ")).not.toContain("do not threaten to close");
  });

  it("always warns about a deferral that capitalises the interest", () => {
    for (const canPay of [true, false]) {
      const c = prepareNegotiation(input({ canPay }))[0];
      expect(c.doNotSay.join(" ")).toContain("CAPITALISES");
    }
  });
});

describe("what a win is worth, and what a win looks like", () => {
  it("prices a rate cut at the reduction, never at the whole rate", () => {
    const c = prepareNegotiation(input({ targetReduction: 0.05 }))[0];
    expect(c.annualValueIfWon.minor).toBe(Math.round(usd(4000).minor * 0.05));
    expect(c.realistic).toContain("3-7 points");
    expect(c.realistic).toContain("24.99% going to zero is not");
  });

  it("never prices a reduction larger than the rate being paid", () => {
    const cheap: AccountPosition = { ...CARD, apr: 0.02 };
    const c = prepareNegotiation(input({ position: position([cheap]), targetReduction: 0.05 }))[0];
    expect(c.annualValueIfWon.minor).toBe(Math.round(usd(4000).minor * 0.02));
  });

  it("adds up every ask, and the total is contingent by construction", () => {
    const fees = auditFees([tx("2026-06-05", "LATE FEE", -39, "a")], "USD");
    const cases = prepareNegotiation(input({ fees }));
    expect(totalIfEveryAskLands(cases, "USD").minor).toBe(
      cases.reduce((n, c) => n + c.annualValueIfWon.minor, 0),
    );
  });

  it("says a written-off balance is not a normal hardship outcome", () => {
    const c = prepareNegotiation(input({ canPay: false }))[0];
    expect(c.realistic).toContain("reported CURRENT");
    expect(c.realistic).toContain("written-off balance is not");
  });
});
